#include "civic/urban/UrbanFabric.hpp"
#include <cmath>
namespace civic::urban {
civic::core::Result<void> UrbanFabricStore::upsert_building(BuildingV2 b) noexcept {auto parcel_exists=[&](civic::core::ParcelId id){return cadastre_?cadastre_->contains_live(id):fallback_parcels_.contains(id);};if(b.id.value()==0||!parcel_exists(b.parcel_id))return std::unexpected(civic::core::error(civic::core::ErrorCode::invalid_state,"building references non-live parcel"));if(!b.footprint.vertices.empty()){auto canon=civic::geometry::canonicalize(b.footprint);if(!canon)return std::unexpected(canon.error());b.footprint=*canon;}if(!std::isfinite(b.gross_floor_area_m2)||b.gross_floor_area_m2<0||!std::isfinite(b.height_meters)||b.height_meters<0)return std::unexpected(civic::core::error(civic::core::ErrorCode::invalid_argument,"invalid building dimensions"));buildings_[b.id]=std::move(b);return {};}
civic::core::Result<void> UrbanFabricStore::validate() const noexcept {for(const auto&[_,b]:buildings_){auto exists=cadastre_?cadastre_->contains_live(b.parcel_id):fallback_parcels_.contains(b.parcel_id);if(!exists)return std::unexpected(civic::core::error(civic::core::ErrorCode::invariant_failure,"building references non-live parcel"));if(b.lifecycle.condition<0||b.lifecycle.condition>100)return std::unexpected(civic::core::error(civic::core::ErrorCode::invariant_failure,"building condition out of range"));}return {};}
}
